#include "storage_engine.h"
#include "errors.h"
#include <cstdlib>
#include <iomanip>
#include <iostream>
using namespace flashforge;
namespace {
void usage(){std::cerr<<"Usage: flashforge [--data DIR] <put|get|update|delete|list|stats|gc|observe|diagnose|metrics|incidents> ...\n";}
void printDecisions(const std::vector<EngineeringDecision>& decisions){
 if(decisions.empty()){std::cout<<"Health: HEALTHY\nNo actionable reliability problems detected.\n";return;}
 for(const auto&d:decisions){std::cout<<d.severity<<"  "<<d.diagnosis<<"\nConfidence: "<<std::fixed<<std::setprecision(0)<<d.confidence*100<<"%\nEvidence: "<<d.evidence<<"\nDecision: "<<d.recommendation<<"\n\n";}
}
}
int main(int argc,char**argv){try{int i=1;std::filesystem::path root="data";if(i+1<argc&&std::string(argv[i])=="--data"){root=argv[i+1];i+=2;}if(i>=argc){usage();return 2;}StorageEngine e(root);std::string cmd=argv[i++];if(cmd=="put"&&i<argc){std::cout<<e.put(argv[i])<<'\n';}else if(cmd=="get"&&i+1<argc){e.get(argv[i],argv[i+1]);std::cout<<"restored\n";}else if(cmd=="update"&&i+1<argc){e.update(argv[i],argv[i+1]);std::cout<<"updated\n";}else if(cmd=="delete"&&i<argc){e.deleteFile(argv[i]);std::cout<<"deleted\n";}else if(cmd=="list"){for(const auto&f:e.listFiles())std::cout<<f.file_id<<'\t'<<f.logical_size<<'\t'<<f.version<<'\t'<<f.original_filename<<'\n';}else if(cmd=="stats"){auto s=e.stats();std::cout<<"Logical storage:     "<<s.logical_size<<" bytes\nPhysical storage:    "<<s.physical_size<<" bytes\nSpace saved:         "<<s.space_saved<<" bytes\nDedup ratio:         "<<std::fixed<<std::setprecision(2)<<s.dedup_ratio<<"x\nUnique chunks:       "<<s.unique_chunks<<"\nChunk references:    "<<s.total_chunk_references<<"\nFiles:               "<<s.file_count<<'\n';}else if(cmd=="gc"){auto s=e.collectGarbage();std::cout<<"Chunks scanned: "<<s.chunks_scanned<<"\nChunks deleted: "<<s.chunks_deleted<<"\nBytes reclaimed: "<<s.bytes_reclaimed<<'\n';}else if(cmd=="observe"){auto r=e.observabilityReport();std::cout<<"FlashForge Observability\n\n";if(r.operations.empty())std::cout<<"No operation samples yet. Run PUT/GET/UPDATE/DELETE/GC first.\n";for(const auto&op:r.operations){std::cout<<std::left<<std::setw(10)<<op.operation<<" count="<<op.count<<" failures="<<op.failures<<" p50="<<op.p50_us/1000.0<<"ms p95="<<op.p95_us/1000.0<<"ms p99="<<op.p99_us/1000.0<<"ms";if(op.wal_fsync_us)std::cout<<" avg-wal-fsync="<<(op.wal_fsync_us/op.count)/1000.0<<"ms avg-metadata-fsync="<<(op.metadata_fsync_us/op.count)/1000.0<<"ms";if(op.fault_delay_us)std::cout<<" [TEST FAULT INJECTION]";std::cout<<'\n';}std::cout<<"Dedup hit ratio:     "<<std::fixed<<std::setprecision(1)<<r.dedup_hit_ratio*100<<"%\nChecksum failures:   "<<r.checksum_failures<<"\nGC bytes reclaimed:  "<<r.gc_reclaimed<<"\nTelemetry dropped:   "<<r.telemetry_samples_dropped<<"\nFilesystem free:     "<<r.system.filesystem_free_bytes<<" bytes\nLinux signals:       "<<(r.system.linux_signals_available?"available":"unavailable on this host")<<"\n\n";printDecisions(e.diagnose());}else if(cmd=="diagnose"||cmd=="incidents"){printDecisions(e.diagnose());}else if(cmd=="metrics"){std::string format=(i+1<argc&&std::string(argv[i])=="--format")?argv[i+1]:"json";if(format=="prometheus")std::cout<<e.metricsPrometheus();else if(format=="json")std::cout<<e.metricsJson()<<'\n';else throw StorageException("metrics format must be json or prometheus");}else{usage();return 2;}return 0;}catch(const std::exception&e){std::cerr<<"flashforge: "<<e.what()<<'\n';return 1;}}
